starter:
class managed_resource:
    def __init__(self, resource):
        pass

    def __enter__(self):
        pass

    def __exit__(self, exc_type, exc, tb):
        pass

tests.check:
class R:
    def __init__(self): self.closed=False
    def close(self): self.closed=True
r=R()
try:
    with managed_resource(r): raise ValueError('x')
except ValueError: pass
else: raise AssertionError()
assert r.closed

class R:
    def close(self): pass
try:
    with managed_resource(R()): raise RuntimeError('boom')
except RuntimeError: pass
else: raise AssertionError()

class R:
    def close(self): pass
assert managed_resource(R()).__exit__(None,None,None) is None

